from __future__ import annotations

from typing import Any


def insecure_compare(left: str, right: str) -> tuple[bool, int]:
    a = left.strip()
    b = right.strip()
    if len(a) != len(b):
        return False, 1
    steps = 0
    for idx, char in enumerate(a):
        steps += 1
        if char != b[idx]:
            return False, steps
    return True, steps


def constant_time_compare(left: str, right: str) -> tuple[bool, int]:
    a = left.strip()
    b = right.strip()
    max_len = max(len(a), len(b))
    result = 0
    steps = 0
    for idx in range(max_len):
        ca = ord(a[idx]) if idx < len(a) else 0
        cb = ord(b[idx]) if idx < len(b) else 0
        result |= ca ^ cb
        steps += 1
    return result == 0 and len(a) == len(b), steps


def compare(left: str, right: str, mode: str = "insecure") -> tuple[bool, int]:
    if mode.strip().lower() == "constant":
        return constant_time_compare(left, right)
    return insecure_compare(left, right)


def mismatch_prefix(left: str, right: str) -> int:
    a = left.strip()
    b = right.strip()
    count = 0
    for idx in range(min(len(a), len(b))):
        if a[idx] != b[idx]:
            break
        count += 1
    return count


def compare_report(left: str, right: str, mode: str = "insecure") -> dict[str, Any]:
    ok, steps = compare(left, right, mode=mode)
    return {
        "ok": ok,
        "steps": steps,
        "prefix_match": mismatch_prefix(left, right),
        "mode": mode.strip().lower(),
    }


def choose_mode(config: dict[str, Any]) -> str:
    flag = str(config.get("compare_mode", "insecure")).strip().lower()
    if flag in {"insecure", "constant"}:
        return flag
    return "insecure"


def normalize_hash(value: str) -> str:
    return value.strip().lower()


def compare_hashes(left: str, right: str, mode: str = "insecure") -> tuple[bool, int]:
    return compare(normalize_hash(left), normalize_hash(right), mode=mode)


def safe_steps(steps: int) -> int:
    if steps < 0:
        return 0
    if steps > 10_000:
        return 10_000
    return int(steps)


def classify_steps(steps: int) -> str:
    value = safe_steps(steps)
    if value <= 2:
        return "low"
    if value <= 32:
        return "medium"
    return "high"


def debug_timing_matrix(values: list[str], probe: str, mode: str = "insecure") -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for candidate in values:
        ok, steps = compare(candidate, probe, mode=mode)
        rows.append({"candidate": candidate, "ok": ok, "steps": steps})
    return rows


def zero_knowledge_hint(left: str, right: str) -> str:
    prefix = mismatch_prefix(left, right)
    if prefix == 0:
        return "no-prefix-match"
    if prefix < 4:
        return "short-prefix-match"
    return "long-prefix-match"


def compare_many(left: str, rights: list[str], mode: str = "insecure") -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    for item in rights:
        ok, steps = compare(left, item, mode=mode)
        results.append({"right": item, "ok": ok, "steps": steps})
    best = max(results, key=lambda row: int(row["steps"])) if results else {"right": "", "ok": False, "steps": 0}
    return {"count": len(results), "best": best, "results": results}


def baseline(mode: str = "insecure") -> dict[str, Any]:
    ok, steps = compare("a" * 64, "b" * 64, mode=mode)
    return {"mode": mode, "ok": ok, "steps": steps}


def sample_profiles() -> dict[str, dict[str, Any]]:
    return {
        "insecure": baseline("insecure"),
        "constant": baseline("constant"),
    }


def steps_delta(left: str, right_a: str, right_b: str, mode: str = "insecure") -> int:
    _ok_a, steps_a = compare(left, right_a, mode=mode)
    _ok_b, steps_b = compare(left, right_b, mode=mode)
    return abs(int(steps_a) - int(steps_b))

