from __future__ import annotations

from typing import Any

from audit_stream import AuditStream
from compare_policy import compare_hashes
from metrics_registry import MetricsRegistry
from password_hashing import hash_password
from rate_limiter import RateLimiter
from request_parser import key_for_rate_limit, parse_request, response_shape, scrub, validate_request
from token_issuer import issue_for_request
from user_repo import UserRepo


class LoginService:
    def __init__(
        self,
        *,
        repo: UserRepo,
        limiter: RateLimiter,
        audit: AuditStream,
        metrics: MetricsRegistry,
        compare_mode: str = "insecure",
    ) -> None:
        self._repo = repo
        self._limiter = limiter
        self._audit = audit
        self._metrics = metrics
        self._compare_mode = compare_mode

    def _emit(self, event: str, req: dict[str, Any], extra: dict[str, Any] | None = None) -> None:
        payload = scrub(req)
        payload.update(extra or {})
        self._audit.emit(event, payload)

    def _record_failure(self, key: str, req: dict[str, Any], reason: str, steps: int = 0) -> dict[str, Any]:
        count = self._limiter.record_failure(key)
        self._metrics.inc("login_failed")
        self._emit("login_failed", req, {"reason": reason, "failures": count, "compare_steps": steps})
        return response_shape(False, reason, req["request_id"], steps=steps)

    def login(self, payload: dict[str, Any]) -> dict[str, Any]:
        req = parse_request(payload)
        valid, reason = validate_request(req)
        if not valid:
            self._metrics.inc("login_rejected")
            self._emit("login_rejected", req, {"reason": reason})
            return response_shape(False, reason, req["request_id"])

        key = key_for_rate_limit(req)
        if self._limiter.blocked(key):
            self._metrics.inc("login_rate_limited")
            self._emit("login_rate_limited", req, {})
            return response_shape(False, "rate_limited", req["request_id"])

        user = self._repo.get_user(req["email"])
        if user is None:
            return self._record_failure(key, req, "invalid_credentials", steps=1)

        if bool(user.get("locked", False)):
            self._metrics.inc("login_locked")
            self._emit("login_locked", req, {})
            return response_shape(False, "locked", req["request_id"])

        expected_hash = str(user.get("password_hash", ""))
        salt = str(user.get("salt", ""))
        candidate_hash = hash_password(str(req.get("password", "")), salt)

        # Bug: insecure mode leaks prefix match length through compare_steps.
        ok, steps = compare_hashes(candidate_hash, expected_hash, mode=self._compare_mode)
        if not ok:
            result = self._record_failure(key, req, "invalid_credentials", steps=steps)
            failed_total = self._repo.bump_failure(req["email"])
            if failed_total >= 5:
                self._repo.lock(req["email"])
            return result

        self._limiter.reset(key)
        self._metrics.inc("login_ok")
        token = issue_for_request(req["email"], req["request_id"])
        self._emit("login_ok", req, {"compare_steps": steps})
        return response_shape(True, "authenticated", req["request_id"], token=token, steps=steps)

    def set_compare_mode(self, mode: str) -> None:
        self._compare_mode = mode.strip().lower()

    def compare_mode(self) -> str:
        return self._compare_mode

    def diagnostics(self) -> dict[str, Any]:
        return {
            "compare_mode": self._compare_mode,
            "metrics": self._metrics.snapshot(),
            "audit_events": self._audit.count(),
            "users": self._repo.count(),
        }

    def warmup(self, payloads: list[dict[str, Any]]) -> list[dict[str, Any]]:
        results: list[dict[str, Any]] = []
        for payload in payloads:
            results.append(self.login(payload))
        return results

    def reset_runtime(self) -> None:
        self._limiter.clear()
        self._audit.clear()
        self._metrics.clear()

    def configure(self, config: dict[str, Any]) -> None:
        mode = str(config.get("compare_mode", self._compare_mode)).strip().lower()
        if mode in {"insecure", "constant"}:
            self._compare_mode = mode

    def replay_attempt(self, email: str, password: str, request_id: str = "req-replay") -> dict[str, Any]:
        return self.login({"email": email, "password": password, "request_id": request_id, "ip": "127.0.0.8"})

    def seed_failures(self, email: str, count: int) -> None:
        key = f"{email.strip().lower()}|127.0.0.8"
        for _ in range(max(0, int(count))):
            self._limiter.record_failure(key)

    def unlock_user(self, email: str) -> bool:
        user = self._repo.get_user(email)
        if user is None:
            return False
        user["locked"] = False
        user["failed_attempts"] = 0
        self._repo.save_user(user)
        return True

    def metric(self, key: str) -> int:
        return self._metrics.get(key)

