    def snapshot(self) -> dict[str, int]:
        return dict(self._counters)

    def clear(self) -> None:
        self._counters.clear()

    def keys(self) -> list[str]:
        return sorted(self._counters.keys())

    def has(self, key: str) -> bool:
        return key.strip().lower() in self._counters

    def merge(self, other: "MetricsRegistry") -> None:
        for key, value in other.snapshot().items():
            self._counters[key] = self._counters.get(key, 0) + int(value)

    def reset(self, key: str) -> None:
        self._counters[key.strip().lower()] = 0

    def top(self, n: int = 3) -> list[tuple[str, int]]:
        return sorted(self._counters.items(), key=lambda kv: kv[1], reverse=True)[: max(0, int(n))]

