        k = key.strip().lower()
        if k not in self._counters:
            return False
        del self._counters[k]
        return True

    def total(self) -> int:
        return sum(self._counters.values())

    def prefix(self, key_prefix: str) -> dict[str, int]:
        needle = key_prefix.strip().lower()
        return {k: v for k, v in self._counters.items() if k.startswith(needle)}

