from __future__ import annotations

import hashlib
from typing import Any


def normalize_password(value: str) -> str:
    return value.strip()


def normalize_salt(value: str) -> str:
    return value.strip().lower()


def hash_password(password: str, salt: str) -> str:
    payload = f"{normalize_salt(salt)}::{normalize_password(password)}".encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def stretch_hash(password: str, salt: str, rounds: int = 500) -> str:
    digest = hash_password(password, salt)
    for _ in range(max(1, int(rounds))):
        digest = hashlib.sha256(f"{digest}:{salt}".encode("utf-8")).hexdigest()
    return digest


def verify_password(password: str, salt: str, expected_hash: str) -> bool:
    computed = hash_password(password, salt)
    return computed == expected_hash


def hash_preview(value: str) -> str:
    text = value.strip().lower()
    if len(text) < 12:
        return text
    return text[:6] + "..." + text[-6:]


def valid_hash_shape(value: str) -> bool:
    text = value.strip().lower()
    if len(text) != 64:
        return False
    return all(c in "0123456789abcdef" for c in text)


def safe_hash_or_empty(password: str, salt: str) -> str:
    try:
        return hash_password(password, salt)
    except Exception:
        return ""


def make_salted_user(email: str, password: str, salt: str) -> dict[str, Any]:
    return {
        "email": email.strip().lower(),
        "password_hash": hash_password(password, salt),
        "salt": salt.strip().lower(),
        "locked": False,
        "failed_attempts": 0,
    }


def migrate_hash_if_needed(user: dict[str, Any], new_rounds: int = 700) -> dict[str, Any]:
    row = dict(user)
    old_hash = str(row.get("password_hash", ""))
    salt = str(row.get("salt", ""))
    if not valid_hash_shape(old_hash):
        row["password_hash"] = stretch_hash(old_hash, salt, rounds=new_rounds)
        row["hash_version"] = "v2"
        return row
    row.setdefault("hash_version", "v1")
    return row


def masked_user(user: dict[str, Any]) -> dict[str, Any]:
    row = dict(user)
    row["password_hash"] = hash_preview(str(row.get("password_hash", "")))
    return row


def hash_bundle(password: str, salt: str) -> dict[str, Any]:
    first = hash_password(password, salt)
    stretched = stretch_hash(password, salt, rounds=50)
    return {
        "hash": first,
        "stretched": stretched,
        "valid": valid_hash_shape(first),
        "salt": normalize_salt(salt),
    }


def compare_hashes(left: str, right: str) -> bool:
    return str(left).strip().lower() == str(right).strip().lower()


def rotate_salt(user: dict[str, Any], new_salt: str, password_guess: str = "") -> dict[str, Any]:
    row = dict(user)
    salt = normalize_salt(new_salt)
    row["salt"] = salt
    if password_guess:
        row["password_hash"] = hash_password(password_guess, salt)
    return row


def password_strength(password: str) -> dict[str, Any]:
    text = password or ""
    return {
        "length": len(text),
        "has_upper": any(c.isupper() for c in text),
        "has_lower": any(c.islower() for c in text),
        "has_digit": any(c.isdigit() for c in text),
    }


def looks_strong(password: str) -> bool:
    profile = password_strength(password)
    return bool(
        profile["length"] >= 8
        and profile["has_upper"]
        and profile["has_lower"]
        and profile["has_digit"]
    )

