class RateLimiter:
    def __init__(self, threshold: int = 5) -> None:
        self._threshold = int(threshold)
        self._counts: dict[str, int] = {}

    def record_failure(self, key: str) -> int:
        k = key.strip().lower()
        self._counts[k] = self._counts.get(k, 0) + 1
        return self._counts[k]

    def reset(self, key: str) -> None:
        k = key.strip().lower()
        if k in self._counts:
            self._counts[k] = 0

    def blocked(self, key: str) -> bool:
        return self._counts.get(key.strip().lower(), 0) >= self._threshold

    def count(self, key: str) -> int:
        return int(self._counts.get(key.strip().lower(), 0))

    def clear(self) -> None:
        self._counts.clear()

    def snapshot(self) -> dict[str, Any]:
        return {"threshold": self._threshold, "counts": dict(self._counts)}

    def keys(self) -> list[str]:
        return sorted(self._counts.keys())

    def set_threshold(self, threshold: int) -> None:
        value = int(threshold)
        if value < 1:
            value = 1
        self._threshold = value

    def threshold(self) -> int:
        return self._threshold

    def remove(self, key: str) -> bool:
        k = key.strip().lower()
        if k not in self._counts:
            return False
        del self._counts[k]
        return True

    def total_failures(self) -> int:
        return sum(self._counts.values())

    def blocked_keys(self) -> list[str]:
        return sorted([key for key, value in self._counts.items() if value >= self._threshold])

    def active_keys(self) -> int:
        return len([k for k, v in self._counts.items() if v > 0])

    def restore(self, snapshot: dict[str, Any]) -> None:
        self._threshold = int(snapshot.get("threshold", self._threshold))
        counts = snapshot.get("counts", {})
        if isinstance(counts, dict):
            self._counts = {str(k): int(v) for k, v in counts.items()}

    def export_blocked(self) -> dict[str, int]:
        return {key: value for key, value in self._counts.items() if value >= self._threshold}

