from __future__ import annotations

import hashlib
from typing import Any


def issue_token(email: str, nonce: str) -> str:
    payload = f"{email.strip().lower()}::{nonce.strip()}".encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def token_payload(email: str, nonce: str) -> dict[str, Any]:
    return {
        "token": issue_token(email, nonce),
        "email": email.strip().lower(),
        "nonce": nonce.strip(),
        "type": "session",
    }


def valid_token_shape(value: str) -> bool:
    text = value.strip().lower()
    return len(text) == 64 and all(c in "0123456789abcdef" for c in text)


def token_preview(value: str) -> str:
    text = value.strip()
    if len(text) < 14:
        return text
    return text[:7] + "..." + text[-7:]


def build_nonce(request_id: str) -> str:
    return hashlib.md5(request_id.strip().encode("utf-8")).hexdigest()[:16]


def issue_for_request(email: str, request_id: str) -> str:
    return issue_token(email, build_nonce(request_id))


def token_meta(email: str, request_id: str) -> dict[str, Any]:
    token = issue_for_request(email, request_id)
    return {
        "token": token,
        "preview": token_preview(token),
        "email": email.strip().lower(),
    }


def batch_issue(emails: list[str], request_id: str) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for email in emails:
        rows.append(token_meta(email, request_id))
    return rows


def rotate_nonce(request_id: str, salt: str) -> str:
    return build_nonce(request_id + "::" + salt.strip())


def issue_with_salt(email: str, request_id: str, salt: str) -> str:
    nonce = rotate_nonce(request_id, salt)
    return issue_token(email, nonce)

